import {createPixelDetector,VideoTracker} from './tracking-model.js';
const lab=document.getElementById('lab');lab.setAttribute('aria-label','Match Lab');
const node=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
const modes=node('div',undefined,'vt-modes');modes.setAttribute('role','group');modes.setAttribute('aria-label','Match Lab workspace');
const panel=node('section',undefined,'video-tracking');panel.setAttribute('aria-label','Synthetic video tracking');
panel.innerHTML=`<div class="vt-heading"><div><span class="eyebrow">VIDEO INTELLIGENCE / CONTROLLED SYNTHETIC CAPTURE</span><h2>From pixels.<em> To proof.</em></h2><p>Eight fictional players. One continuous minute. Identify, track, measure and inspect.</p></div><span class="vt-local">ON-DEVICE ANALYSIS · NO AI CREDITS</span></div><div class="vt-layout"><div class="vt-main"><div class="vt-screen"><video playsinline controls preload="metadata" poster="assets/tracking/poster.jpg" aria-label="One-minute synthetic training match"><source src="assets/tracking/training-minute.mp4" type="video/mp4"></video><canvas class="vt-overlay" aria-hidden="true"></canvas><span class="vt-source">SYNTHETIC TRAINING VIDEO · COLOUR-MARKER IDENTIFICATION</span></div><div class="vt-controls"><button class="red-button" data-action="start">▶ Analyze the full minute</button><button class="outline-button" data-action="reset">Reset</button><label><input type="checkbox" data-option="labels" checked> Player names</label><label><input type="checkbox" data-option="trails" checked> Movement trails</label></div><p class="vt-status" role="status">Loading calibration and pass-quality model…</p><div class="vt-stats"></div><article class="vt-moment"><span class="eyebrow">THE NEXT STORY STARTS WITH EVIDENCE</span><h3>Press play. Let the pixels speak.</h3><p>Passes and shot candidates appear only after the ball movement is observed.</p></article><details class="vt-method"><summary>Challenge the detector / inspect its assumptions</summary><div class="vt-controls"><label><input type="checkbox" data-option="occludeBall"> Hide the ball from the detector</label><label><input type="checkbox" data-option="hideTracking"> Withhold player markers</label></div><p>These controls remove evidence before detection results reach event inference. Changing them resets the current analysis. Missing evidence is reported, not filled with the known event schedule.</p><p>Names come from enrolled coloured kit markers—not face recognition. The fixed camera is calibrated to a 105 × 68 m pitch. Ball speed is a ground-plane trajectory estimate; aerial balls and moving cameras are unsupported. Shots are directional, high-speed candidates, not certified goals.</p><p>Pass difficulty is a logistic model trained on synthetic outcomes using release-time distance, nearest defender and lane clearance. It is not a calibrated professional-football completion probability. This demo analyzes its own marked training footage; it does not automatically analyze the cinematic film.</p></details></div><aside class="vt-side"><div class="vt-tabs" role="group" aria-label="Tracking detail"><button data-tab="events" aria-pressed="true">Event wire</button><button data-tab="players" aria-pressed="false">Players</button><button data-tab="proof" aria-pressed="false">Validation</button></div><div class="vt-side-content"></div><button class="outline-button vt-export" disabled>Export observed evidence ↓</button></aside></div>`;
lab.querySelector('.lab-banner').after(modes,panel);
const sim=document.getElementById('simulation'),frameStatus=document.getElementById('lab-frame-status'),banner=lab.querySelector('.lab-banner p'),originalCopy=banner.textContent;
for(const[id,label]of [['video','Video tracking'],['fixture','Full-match simulator']]){const b=node('button',label);b.setAttribute('aria-pressed',String(id==='video'));b.onclick=()=>{panel.hidden=id!=='video';sim.hidden=id==='video';frameStatus.hidden=id==='video';banner.textContent=id==='video'?'Analyze a controlled video or generate a full synthetic fixture. Every measurement declares its source.':originalCopy;modes.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));if(id!=='video')video.pause();};modes.append(b);}sim.hidden=true;frameStatus.hidden=true;banner.textContent='Analyze a controlled video or generate a full synthetic fixture. Every measurement declares its source.';
const video=panel.querySelector('video'),overlay=panel.querySelector('canvas'),ctx=overlay.getContext('2d'),pixels=document.createElement('canvas');pixels.width=480;pixels.height=320;const pc=pixels.getContext('2d',{willReadFrequently:true});
let cal,model,validation,detector,tracker,current=null,tab='events',lastTime=-1,lastPaint=-1,eventCount=-1,busy=false,hasRun=false;
const options=()=>Object.fromEntries([...panel.querySelectorAll('[data-option]')].map(n=>[n.dataset.option,n.checked]));
function clear(){tracker?.reset();lastTime=-1;lastPaint=-1;eventCount=-1;current=null;hasRun=false;ctx.clearRect(0,0,overlay.width,overlay.height);panel.querySelector('.vt-export').disabled=true;render();}
function format(v,d=1){return Number.isFinite(v)?v.toFixed(d):'—';}
function identity(id){return cal?.roster.find(p=>p.id===id)?.name||'Unknown player';}
function render(){
 const list=panel.querySelector('.vt-side-content');const expanded=new Set([...list.querySelectorAll('details[open]')].map(n=>n.dataset.event));const scroll=list.scrollTop;list.replaceChildren();const events=current?.events||[];
 panel.querySelector('.vt-stats').replaceChildren(...[[String(current?.players.length??0)+'/8','Players identified'],[String(events.filter(e=>e.type==='pass').length),'Completed passes'],[format(current?.ballSpeed),'Ball km/h · recent'],[format(events.filter(e=>e.type==='shot').at(-1)?.speed),'Last shot km/h']].map(([v,l])=>{const c=node('div');c.append(node('strong',v),node('span',l));return c;}));
 if(tab==='events'){if(!events.length)list.append(node('p','Waiting for a completed transfer. No event schedule feeds the detector.','vt-empty'));for(const e of [...events].reverse()){const card=node('article',undefined,'vt-event'),head=node('div',undefined,'vt-event-head');head.append(node('span',e.type==='shot'?'SHOT CANDIDATE':e.type.toUpperCase()),node('time',e.end.toFixed(1)+'s'));card.append(head,node('h3',identity(e.from)+(e.to?' → '+identity(e.to):'')),node('p',`${format(e.distance)} m · ${format(e.speed)} km/h`));if(e.quality)card.append(node('span',`${e.quality.difficulty}/100 difficulty · synthetic model`,'vt-difficulty'));const d=node('details');d.dataset.event=e.id;d.open=expanded.has(e.id);d.append(node('summary','Why this rating / source frames'));d.append(node('p',e.quality?`At release: ${format(e.quality.distance)} m to receiver, ${format(e.quality.pressure)} m nearest defender, ${format(e.quality.clearance)} m lane clearance. ${format(e.quality.completion*100,0)}% synthetic-model completion estimate.`:'Directional ball flight toward the goal mouth. No calibrated height or goal-line outcome.'));d.append(node('small',`Decoded frames ${e.evidence.firstFrame}–${e.evidence.lastFrame}. Speed uses a linear fit to observed ball positions, metres → kilometres per hour.`));card.append(d);list.append(card);}}
 if(tab==='players')for(const p of cal?.roster||[]){const observed=current?.players.find(x=>x.id===p.id),card=node('article',undefined,'vt-player'),badge=node('span',String(p.id%100),'vt-number');badge.style.setProperty('--kit',`rgb(${p.color.join(',')})`);const info=node('div');info.append(node('h3',p.name),node('small',`${p.role} · ${p.team==='harbor'?'Harbor FC':'Northbridge'}`),node('p',observed?`${format(observed.speed)} km/h · ${format(observed.distance)} m observed travel`:'Marker not currently observed'));card.append(badge,info);list.append(card);} 
 if(tab==='proof'){list.append(node('h3','Test the measurements.'),node('p','Development validation on this compressed video, not a general broadcast benchmark.'));if(validation){for(const[v,l]of [[validation.matchedEvents+'/'+validation.expectedEvents,'Events matched within 0.5 s'],[(validation.playerDetectionRate*100).toFixed(2)+'%','Marker detection across frames'],[format(validation.playerMeanErrorMetres,2)+' m','Mean player position error'],[format(validation.ballMeanErrorMetres,2)+' m','Mean ball position error'],[format(validation.speedMeanAbsoluteErrorKmh,2)+' km/h','Mean event-speed error'],[format(validation.p95ComputeMs,2)+' ms','95th percentile offline frame processing']]){const c=node('div',undefined,'vt-proof-stat');c.append(node('strong',v),node('span',l));list.append(c);}}if(model)list.append(node('p',`Pass model: ${model.train} synthetic training examples / ${model.test} held-out examples. Brier error ${model.brier.toFixed(3)} versus ${model.baselineBrier.toFixed(3)} for a constant baseline; lower is better. This validates fit to a synthetic generator.`));for(const[url,label]of [['validation.json','Video validation + limitations'],['pass-model.json','Model coefficients + calibration bins'],['calibration.json','Pitch calibration + fictional roster']]){const a=node('a',label+' ↗');a.href='assets/tracking/'+url;a.target='_blank';a.rel='noopener';list.append(a);}}
 list.scrollTop=scroll;const e=events.at(-1),moment=panel.querySelector('.vt-moment');if(e){moment.querySelector('h3').textContent=e.type==='shot'?`${identity(e.from)} sends the ball toward goal.`:`${identity(e.from)} finds ${identity(e.to)}.`;moment.querySelector('p').textContent=e.type==='shot'?`The observed ground-plane flight averages ${format(e.speed)} km/h. That is a shot candidate; it does not prove a goal.`:e.quality?`A ${format(e.distance)} m transfer, with ${format(e.quality.clearance)} m of passing-lane clearance at release. The synthetic model rates its difficulty ${e.quality.difficulty}/100. Timing alone does not establish the passer’s intention.`:'The transfer is observed, but defender coverage is insufficient for a difficulty rating.';}else{moment.querySelector('h3').textContent='Press play. Let the pixels speak.';moment.querySelector('p').textContent='Passes and shot candidates appear only after the ball movement is observed.';}
}
function draw(){ctx.clearRect(0,0,overlay.width,overlay.height);if(!current)return;const o=options(),toPixel=p=>({x:cal.pitch.x+p.x*cal.pitch.scaleX,y:cal.pitch.y+p.y*cal.pitch.scaleY});ctx.font='bold 16px Arial';for(const p of current.players){const q=toPixel(p);if(o.trails){const track=tracker.tracks.get(p.id);ctx.beginPath();track.history.forEach((h,i)=>{const v=toPixel(h);i?ctx.lineTo(v.x,v.y):ctx.moveTo(v.x,v.y);});ctx.strokeStyle='#f5e681';ctx.lineWidth=2;ctx.stroke();}ctx.strokeStyle=p.team==='harbor'?'#f5e681':'#82c6ff';ctx.lineWidth=1.5;ctx.strokeRect(q.x-12,q.y-32,24,37);if(o.labels){const text=p.name.split(' ').at(-1)+(p.speed>20?' · '+format(p.speed)+' km/h':''),w=ctx.measureText(text).width+12;ctx.fillStyle='rgba(8,16,25,.88)';ctx.fillRect(Math.min(960-w,q.x-w/2),q.y-54,w,22);ctx.fillStyle='#fff';ctx.fillText(text,Math.min(966-w,q.x-w/2+6),q.y-38);}}if(current.ball){const q=toPixel(current.ball);ctx.strokeStyle='#ff83cc';ctx.beginPath();ctx.arc(q.x,q.y,10,0,Math.PI*2);ctx.stroke();}}
function process(t){if(!tracker||busy||Math.abs(t-lastTime)<.085)return;busy=true;try{pc.drawImage(video,0,0,480,320);const frame=detector(pc.getImageData(0,0,480,320).data,480,320,options());current=tracker.update(frame,t);lastTime=t;hasRun=true;panel.querySelector('.vt-export').disabled=false;draw();panel.querySelector('.vt-status').textContent=`${t.toFixed(1)} / 60 s · ${current.status}`;if(current.events.length!==eventCount||t-lastPaint>.8||t<lastPaint){eventCount=current.events.length;lastPaint=t;if(!panel.querySelector('.vt-side-content').contains(document.activeElement))render();}}catch(e){video.pause();panel.querySelector('.vt-status').textContent='Analysis stopped: '+e.message;}finally{busy=false;}}
function next(){if(video.requestVideoFrameCallback)video.requestVideoFrameCallback((_,meta)=>{if(!video.paused)process(meta.mediaTime);next();});else requestAnimationFrame(()=>{if(!video.paused)process(video.currentTime);next();});}
panel.querySelector('[data-action="start"]').onclick=async()=>{if(!tracker)return;clear();video.currentTime=0;try{await video.play();}catch{panel.querySelector('.vt-status').textContent='Tap the video play control to start.';}};
panel.querySelector('[data-action="reset"]').onclick=()=>{video.pause();video.currentTime=0;clear();panel.querySelector('.vt-status').textContent='Reset. No saved event timeline is used.';};
video.addEventListener('seeking',()=>{clear();panel.querySelector('.vt-status').textContent='Seek detected. Analyze forward to build new evidence.';});
for(const b of panel.querySelectorAll('[data-tab]'))b.onclick=()=>{tab=b.dataset.tab;panel.querySelectorAll('[data-tab]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));render();};
for(const c of panel.querySelectorAll('[data-option]'))c.onchange=()=>{if(['occludeBall','hideTracking'].includes(c.dataset.option)){clear();panel.querySelector('.vt-status').textContent='Evidence changed. Analysis restarted at the current video time.';}else draw();};
panel.querySelector('.vt-export').onclick=()=>{if(!hasRun)return;const blob=new Blob([JSON.stringify({source:'compressed synthetic video pixels',calibration:cal,cutoff:current.t,events:current.events,players:current.players,method:model.method,limitations:validation?.limits},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=node('a');a.href=url;a.download='btr-pixel-evidence.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
document.addEventListener('visibilitychange',()=>{if(document.hidden)video.pause();});new MutationObserver(()=>{if(lab.hidden)video.pause();}).observe(lab,{attributes:true,attributeFilter:['hidden']});
try{[cal,model,validation]=await Promise.all(['calibration.json','pass-model.json','validation.json'].map(async name=>{const r=await fetch('assets/tracking/'+name);if(!r.ok)throw Error(name+' unavailable');return r.json();}));detector=createPixelDetector(cal);tracker=new VideoTracker(cal,model);overlay.width=cal.width;overlay.height=cal.height;panel.querySelector('.vt-status').textContent='Ready · fixed-camera calibration loaded · no cloud requests';render();next();}catch(e){panel.querySelector('.vt-status').textContent='Tracking unavailable: '+e.message;panel.querySelector('[data-action="start"]').disabled=true;}
